ee:message.ee:set-payload:
%dw 2.0
output application/json
var action = upper(attributes.method)
var documentType = if (action == "POST") null else attributes.queryParams.documentType
var documentNo   = if (action == "POST") null else attributes.queryParams.documentNo
var lineNo       = attributes.queryParams.lineNo default null
var dwPayload = if (payload is Array<Object>) payload else (payload as Array)
---
{
    requests: dwPayload map (item) -> {
        action: action,
        documentType: documentType,
        documentNo: documentNo,
        lineNo: lineNo,
        body: item
    }
}

%dw 2.0
output application/json
---
{
  requests: payload.requests map (r) ->
    if (r.action == "PATCH" and r.lineNo == null)
      error("lineNo query param is mandatory for PATCH")
    else r
}

%dw 2.0
output application/json

var action = if (attributes.method == "PATCH") "PATCH" else "POST"
var dwPayload = if (payload is Array<Object>) payload else payload.requests

---
{
  requests: dwPayload map (item) -> {
    action: action,
    customerNo: item.No default null,
    body: item
  }
}

%dw 2.0
output application/json
---
{
  requests: payload.requests map (r) ->
    if (r.action == "PATCH" and r.customerNo == null)
      error("Customer No is mandatory for PATCH")
    else r
}

%dw 2.0
output application/json
var company = vars.company
---
{
  requests: payload.requests map (r) -> {
    method: r.action,
    url:
      if (r.action == "PATCH")
        "Company('" ++ company ++ "')/Customer_Card_Excel(No='" ++ r.customerNo ++ "')"
      else
        "Company('" ++ company ++ "')/Customer_Card_Excel",
    headers:
      {
        "Content-Type": "application/json",
        "Isolation": "Snapshot"
      }
      ++ (if (r.action == "PATCH") { "If-Match": "*" } else {}),
    body: r.body
  }
}

%dw 2.0
output application/json

var action = if (attributes.method == "PATCH") "PATCH" else "POST"
var dwPayload = if (payload is Array<Object>) payload else payload.requests

