set-variable.value:
#[output application/json
---
{
  BC_Tenant_GUID: vars.tenantGuid,
  BC_Tenant_Name: vars.company replace " " with "%20"
}]

set-payload.value:
#[output application/json
---
{
  tenantGuid: vars.tenantGuid,
  message: "No MuleSoft configuration available for tenantGuid"
}]

#[output application/json
---
{
  tenantGuid: vars.tenantGuid,
  message: "Unexpected error occurred during DB query for tenantGuid"
}]
